/**
 * Stand-in for @deepseek-ai/schemastery: chainable schema objects carrying only defaults.
 * The Host half never parses a Config in this test; it receives the resolved object directly.
 */
class Node {
  constructor(defaultValue) {
    this.meta = { default: defaultValue }
  }
  default(value) {
    this.meta.default = value
    return this
  }
  description(text) {
    this.meta.description = text
    return this
  }
  min(value) {
    this.meta.min = value
    return this
  }
  max(value) {
    this.meta.max = value
    return this
  }
  step(value) {
    this.meta.step = value
    return this
  }
}

const Schema = {
  string: () => new Node(''),
  number: () => new Node(0),
  object: (shape) => ({ shape }),
}

export default Schema
